using System.Text.Json;
using Game.Westworld;
using Westworld.Scapi.Adapter;
int n=0;void Check(bool v,string name){n++;if(!v)throw new Exception(name);}void Throws(Action a,string name){bool caught=false;try{a();}catch(ArgumentException){caught=true;}Check(caught,name);}
JsonElement J(string s)=>JsonDocument.Parse(s).RootElement.Clone();
var sid=Guid.NewGuid();var aid=Guid.NewGuid();var oid=Guid.NewGuid();
const string entity="{\"reference\":\"e1\",\"name\":\"任意可见生物\",\"position\":{\"x\":1,\"y\":2,\"z\":3},\"distance\":2}";
const string drop="{\"reference\":\"d1\",\"value\":88,\"count\":2,\"position\":{\"x\":2,\"y\":2,\"z\":3},\"distance\":3}";
JsonElement Observation(string entities=entity,string drops=drop)=>J("{\"gameTime\":5,\"entities\":["+entities+"],\"pickables\":["+drops+"]}");
HuntingVisibleProfile P(JsonElement data,double time=10,Guid? actor=null,Guid? obs=null)=>NativeHuntingTools.ProjectObservation(sid,actor??aid,obs??oid,time,data);
var p=P(Observation());Check(p.Targets.Count==2,"projects actual targets");Check(p.Targets[0].Name=="任意可见生物","no species selection");Check(p.Targets[0].Position.X==1,"native position copied");Check(p.Targets[0].Value is null,"entity not invented food");Check(p.Targets[1].Count==2,"observed drop quantity");Check(p.NativeGameTime==5&&p.CapturedAt==10,"separate clocks");
HuntingTargetCheck T(string tool,string target,Guid? session=null,Guid? actor=null,Guid? obs=null,double now=11)=>NativeHuntingTools.CheckTarget(p,session??sid,actor??aid,obs??oid,now,tool,target);
Check(T("act_MeleeAttack","e1").Accepted,"visible entity attack admitted");Check(!T("act_MeleeAttack","d1").Accepted,"drop not animal");Check(T("act_PickUp","d1").Accepted,"visible drop admitted");Check(!T("act_PickUp","e1").Accepted,"animal not pickup");Check(T("act_MoveTo","e1").Accepted,"bounded approach profile");Check(T("act_FaceTowards","d1").Accepted,"aim observed drop");Check(!T("act_Wait","e1").Accepted,"wait not targeted");Check(!T("act_MeleeAttack","hidden").Accepted,"unknown reference denied");Check(!T("act_MeleeAttack","e1",session:Guid.NewGuid()).Accepted,"session isolation");Check(!T("act_MeleeAttack","e1",actor:Guid.NewGuid()).Accepted,"actor isolation");Check(!T("act_MeleeAttack","e1",obs:Guid.NewGuid()).Accepted,"superseded obs denied");Check(T("act_MeleeAttack","e1",now:13).Accepted,"ttl boundary");Check(!T("act_MeleeAttack","e1",now:13.001).Accepted,"expired ttl");Check(!T("act_MeleeAttack","e1",now:9).Accepted,"time regressed");Check(!T("act_MeleeAttack","e1",now:double.NaN).Accepted,"nan time");
Throws(()=>P(Observation(entity+","+entity)),"duplicate ref");Throws(()=>P(Observation(entity,drop.Replace("d1","e1"))),"cross-kind duplicate");Throws(()=>P(Observation(drops:drop.Replace("\"count\":2","\"count\":0"))),"empty drop denied");Throws(()=>P(Observation(entity.Replace("\"distance\":2","\"distance\":17"))),"radius denied");Throws(()=>P(Observation(),double.NaN),"nan capture time");Throws(()=>NativeHuntingTools.ProjectObservation(Guid.Empty,aid,oid,10,Observation()),"empty scope");
var next=P(Observation("",drop),11,obs:Guid.NewGuid());Check(!NativeHuntingTools.CheckTarget(next,sid,aid,next.ObservationId,11,"act_MeleeAttack","e1").Accepted,"disappeared not current");Check(NativeHuntingTools.NewlyObservedDrops(p,next).Count==0,"same drop not new");var more=P(Observation("",drop.Replace("d1","d2")),12,obs:Guid.NewGuid());Check(NativeHuntingTools.NewlyObservedDrops(next,more).Count==1,"newly observed not attributed");Throws(()=>NativeHuntingTools.NewlyObservedDrops(p,P(Observation(),11,Guid.NewGuid())),"drop cross actor denied");Throws(()=>NativeHuntingTools.NewlyObservedDrops(p,P(Observation(),9)),"drop reversed time denied");
HuntingReceipt R(string tool,string status="succeeded",int count=1)=>NativeHuntingTools.ClassifyAction(tool,J($"{{\"action\":\"{tool[4..]}\",\"status\":\"{status}\",\"affectedCount\":{count},\"failure\":\"none\"}}"));
Check(R("act_MeleeAttack").Effect=="hit_death_unconfirmed","hit not kill");Check(R("act_MeleeAttack").Death=="unknown","death unknown");Check(R("act_MeleeAttack",count:0).Effect=="no_damage_proven","zero not false kill");Check(R("act_MeleeAttack","failed",0).Effect=="not_completed","cooldown failed not miss");Check(R("act_MeleeAttack","running",0).Effect=="pending","running not success");Check(R("act_MeleeAttack","cancelled",0).Effect=="cancelled","cancellation");Check(R("act_PickUp").Effect=="picked_up_source_unconfirmed","pickup not owner claim");Check(R("act_PickUp",count:0).Effect=="no_pickup_proven","zero pickup");Check(R("act_Wait").Effect=="wait_completed_loot_unconfirmed","waiting not loot");Check(R("act_MoveTo").Effect=="reached_snapshot_position","not dynamic follow");Check(R("act_FaceTowards").Effect=="aimed","aim only");Check(R("act_MeleeAttack",count:-1).Effect=="unknown","negative count unknown");Check(NativeHuntingTools.ClassifyAction("act_MeleeAttack",J("null")).Effect=="unknown","no receipt");Check(NativeHuntingTools.ClassifyAction("act_MeleeAttack",J("{\"status\":\"succeeded\",\"action\":\"Wait\",\"affectedCount\":1}")).Effect=="unknown","other action cannot prove hit");Check(NativeHuntingTools.ClassifyAction("act_MeleeAttack",J("{\"status\":\"succeeded\",\"action\":\"MeleeAttack\"}")).Effect=="unknown","missing count not miss");
var definitions=new[]{new ActorToolDefinition("act_MeleeAttack","native",J("{\"type\":\"object\"}")),new ActorToolDefinition("unavailable","not related",J("{}")),new ActorToolDefinition("act_MoveTo","native move",J("{\"required\":[\"destination\"]}"))};var contracts=NativeHuntingTools.Describe(definitions);Check(contracts.Count==2,"do not invent availability");Check(contracts[0].NativeTool.Parameters.GetProperty("type").GetString()=="object","actual schema unchanged");Check(contracts[1].SuggestedMaxSeconds==2,"short approach recommendation");Check(contracts[1].EvidenceRule.Contains("NOT a live tracking"),"no tracking promise");Check(NativeHuntingTools.Describe([]).Count==0,"empty capabilities stay empty");
Console.WriteLine($"{n}/{n} passed");
